package com.ebuddy.service;
import com.ebuddy.domain.*; import com.ebuddy.repo.*; import com.ebuddy.web.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ContactService { final UserRepository users; final ContactRepository contacts; public ContactService(UserRepository u,ContactRepository c){users=u;contacts=c;} @Transactional public ApiModels.ContactView add(UUID owner,String username){UserEntity target=users.findByUsernameNorm(username.toLowerCase()).orElseThrow(NotFoundException::new);if(target.getId().equals(owner))throw new ConflictException("Cannot add yourself");ContactEntity c=new ContactEntity(owner,target.getId());contacts.save(c);return view(target,c);} @Transactional public ApiModels.ContactView update(UUID owner,UUID target,String state,String alias){ContactEntity c=contacts.findAll().stream().filter(x->x.owner().equals(owner)&&x.contact().equals(target)).findFirst().orElseThrow(NotFoundException::new);c.setState(ContactState.valueOf(state));c.setAlias(alias);contacts.save(c);return view(users.findById(target).orElseThrow(NotFoundException::new),c);} @Transactional(readOnly=true) public List<ApiModels.ContactView> list(UUID owner){return contacts.findByIdOwnerUserIdOrderByUpdatedAtDesc(owner).stream().map(c->view(users.findById(c.contact()).orElseThrow(NotFoundException::new),c)).toList();} private ApiModels.ContactView view(UserEntity u,ContactEntity c){return new ApiModels.ContactView(new ApiModels.UserView(u.getId(),u.getUsername(),u.getDisplayName()),c.getState().name(),c.getAlias());} }
